"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[226],{8174(e){e.exports=JSON.parse('{"title":"Web Component\ub294 \uae30\uc874 \ud504\ub808\uc784\uc6cc\ud06c\uc640 \uc0c1\ud638\ubcf4\uc644\uc801\uc774\ub2e4.","date":"2024-02-06","coverUrl":null,"html":"<h2 data-notion-block-id=\\"be73799f-a514-4f83-a14e-c0ec0cdd2dfe\\" id=\\"be73799f-a514-4f83-a14e-c0ec0cdd2dfe\\">Web Component\ub294 \uae30\uc874 \ud504\ub808\uc784\uc6cc\ud06c\uc640 \uc0c1\ud638\ubcf4\uc644\uc801\uc774\ub2e4.</h2><a href=\\"https://jakelazaroff.com/words/the-web-component-success-story/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jakelazaroff.com/words/the-web-component-success-story/</a><p data-notion-block-id=\\"f7bb384b-d343-46c1-9017-14b50d970dc1\\"><b>\uc2ec\uc724\uc12d</b>: \uc6f9 \ucef4\ud3ec\ub10c\ud2b8\ub294 \uc6f9 \ud45c\uc900\uc73c\ub85c \uc790\ub9ac\uc7a1\uc558\uc73c\uba70 <a href=\\"https://naildrivin5.com/blog/2024/01/24/web-components-in-earnest.html\\">\ub3c4\uc785 \ud6c4\uae30 \uae00</a>\ub3c4 \uba87 \uad70\ub370\uc5d0\uc11c \ub098\uc624\uba74\uc11c \uad00\uc2ec\uc744 \uac00\uc9c8 \uc218\ub3c4 \uc788\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc774 \uae00\uc740 \uc6f9 \ucef4\ud3ec\ub10c\ud2b8\ub97c \uae30\uc874 UI \ud504\ub808\uc784\uc6cc\ud06c(ex. React, Vue\u2026)\ub97c \ub300\uccb4\ud558\ub294 \uae30\uc220\uc774 \uc544\ub2c8\uace0, \uac19\uc774 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uc744 \uac15\uc870\ud558\uba70 \ud30c\ud3b8\ud654\ub41c \ud504\ub808\uc784\uc6cc\ud06c\ub4e4\uc744 \uc6f9 \ucef4\ud3ec\ub10c\ud2b8\ub85c \ubaa8\uc744 \uc218\ub3c4 \uc788\ub2e4\ub294 \ubc14\ub78c\uc744 \uac19\uc774 \uc801\uc5c8\uc2b5\ub2c8\ub2e4. \uc6f9 \ucef4\ud3ec\ub10c\ud2b8\uc758 \ud76c\ub9dd\uc744 \ub9d0\ud558\uc9c0\ub9cc <a href=\\"https://daverupert.com/2023/07/why-not-webcomponents/\\">\uc774\ub7f0 \ub2e8\uc810\ub3c4 \uc788\uc2b5\ub2c8\ub2e4</a></p><h2 data-notion-block-id=\\"80cfed4e-4f31-4602-b2f1-7a6e89902063\\" id=\\"80cfed4e-4f31-4602-b2f1-7a6e89902063\\">\uc774\ubca4\ud2b8 \ub8e8\ud504\uc758 \uc9c4\uc2e4</h2><a href=\\"https://blog.frontend-almanac.com/event-loop-myths-and-reality\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.frontend-almanac.com/event-loop-myths-and-reality</a><p data-notion-block-id=\\"d134af33-6fa1-439e-a3eb-bf0fe942cc69\\"><b>\uc2ec\uc724\uc12d</b>: \uc218\uc5c6\uc774 \ub9ce\uc740 \ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790\ub4e4\uc774 \ubcf8 What the heck is the event loop anyway?\ub294 \uc544\uc9c1\ub3c4 \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc774 \ubcf4\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \uae30\uc0ac\ub294 \uc218\ub9ce\uc740 (\ud30c\uc0dd\ub41c \uae00\uc758) \uc774\ubca4\ud2b8 \ub8e8\ud504\uc758 \uc8fc\uc7a5\uc744 HTML \ud45c\uc900\uacfc ECMA \ud45c\uc900\uc744 \ud1b5\ud574 \ud30c\ud5e4\uce58\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uacb0\uad6d \uba85\ud655\ud55c \uc774\ubca4\ud2b8 \ub8e8\ud504\ub294 \uc5c6\uc73c\uba70 \uba85\ud655\ud55c \uc774\ubca4\ud2b8 \ub8e8\ud504\ub97c \uc54c\uace0 \uc2f6\ub2e4\uba74 \ub7f0\ud0c0\uc784\uc5d0\uc11c \uc0ac\uc6a9\ud558\uace0 \uc788\ub294 API\ub97c \ubd10\uc57c \ud55c\ub2e4\ub294 \uac83\uc744 \uc54c\ub824\uc8fc\uace0 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"e78a681d-104b-4ae5-a305-e1369a81115e\\" id=\\"e78a681d-104b-4ae5-a305-e1369a81115e\\">2023 React Native \uc124\ubb38\uc870\uc0ac</h2><a href=\\"https://results.stateofreactnative.com/react-native-specific-features/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://results.stateofreactnative.com/react-native-specific-features/</a><p data-notion-block-id=\\"cff1a3a2-0035-4ecf-a54e-6d7f57aa7a11\\"><b>\uc2ec\uc724\uc12d</b>: State of JS\uac00 \uc778\uae30\ub97c \ub04c\uc5b4\uc11c \uadf8\ub7f0\uc9c0 \uc5ec\ub7ec \uacf3\uc5d0\uc11c \uc124\ubb38\uc870\uc0ac\ub97c \ud558\ub124\uc694. \uc8fc\ubaa9\ud560 \ub9cc\ud55c \ubd80\ubd84\uc740 \uaf64 \ucd5c\uadfc\uc5d0 \uc801\uc6a9\ub41c Hermes runtime\uacfc New Architechture\uc774 \uc801\uc6a9\ub41c \ube44\uc728\uc774 \uc5b4\ub290\uc815\ub3c4 \uc788\ub2e4\ub294 \uac83\uacfc Expo \uad00\ub828 \ubaa8\ub4c8(Router, EAS build)\uc758 Retention\uc774 \ub192\ub2e4\ub294 \ubd80\ubd84\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"ec4cbc48-3eec-4ac6-a526-685338f12306\\" id=\\"ec4cbc48-3eec-4ac6-a526-685338f12306\\">pnpm\uc758 \ubca4\uce58\ub9c8\ud06c</h2><a href=\\"https://pnpm.io/benchmarks\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://pnpm.io/benchmarks</a><p data-notion-block-id=\\"5b992dae-f0da-4b60-93e5-5505a0cc1a6f\\">pnpm\uc740 \uc8fc\uae30\uc801\uc73c\ub85c \ubca4\uce58\ub9c8\ud06c\ub97c \uc5c5\ub370\uc774\ud2b8\ud569\ub2c8\ub2e4. clean install \ub9d0\uace0\ub294 \uc88b\uc740 \uc9c0\ud45c\ub97c \ubcf4\uc5ec\uc8fc\uace0 \uc788\ub294 \uac83\uc774 \uc778\uc0c1\uc801\uc774\ub124\uc694.</p><h2 data-notion-block-id=\\"a7149fc6-b56a-405b-be3c-004fdbe51c8b\\" id=\\"a7149fc6-b56a-405b-be3c-004fdbe51c8b\\">\uc774\ubc88\uc8fc\ub3c4 \ub098\uc624\ub294 Next.js App Router \uace0\uac1d\uc758 \uc18c\ub9ac</h2><a href=\\"https://www.flightcontrol.dev/blog/nextjs-app-router-migration-the-good-bad-and-ugly\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.flightcontrol.dev/blog/nextjs-app-router-migration-the-good-bad-and-ugly</a><p data-notion-block-id=\\"e141786a-d19e-4ecf-bb27-ce93b077b549\\">\uc544\uc9c1 \ubd88\uc548\uc815\ud558\ub2e4\ub294 \uc18c\uc2dd\uc774 \ub610 \ub098\uc654\ub2e4\ub294 \uac83\ub9cc \uc54c\uc544\ub450\uc154\ub3c4 \ub098\uc058\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.</p>"}')}}]);